import { BellIcon, CheckIcon, RefreshIcon, MailIcon, ShieldIcon, WarnIcon, MessageIcon, MonitorIcon, TrashIcon, CloseIcon } from "./icons";
import type * as ReactNS from "react";

import {
  deleteInboxEvent,
  fetchInboxEvents,
  fetchRoomApprovals,
  fetchRoomMentions,
  fetchTeamAttention,
  fetchTeamsStructure,
  markInboxRead,
  sendApprovalCommand,
  teamRowToAttentionItem,
  type AttentionItem,
  type AttentionPayload,
  type InboxEvent,
  type InviteRoom,
  type RoomApproval,
  type RoomMention,
  type TeamAttentionRow,
} from "../api";
import { AttentionHistoryList } from "./AttentionPanel";
import { senderShort } from "./MessageSearch";
import { usePendingStore } from "../pending/store";
import type { PendingTally } from "../pending/tally";
import { useThemeColors } from "../theme";
import { useT } from "../i18n";
import { useTabActive } from "../tabActivity";
import { usePoller } from "../usePoller";
import { useForceReload } from "../lib/useForceReload";
import { formatChatTime, sevColor } from "../util";

const host = window.QwenPaw.host;
const React = host.React;
const antd = host.antd;

const PRIMARY = "var(--app-accent, #FF7F16)";

/** 通知中心：宿主 /console/inbox 事件流聚合。
 * 与 OS 通知/MenuBar 铃铛同一事件源（useOsNotifyPoller 同款端点）。
 * 30s 轮询 + 未读/全部筛选 + 全部已读 + 单条删除 + 待审批入口。
 * refreshTick（SSE 事件驱动， IM 式触发）：变化时立即刷新，
 * 无需等轮询周期。 */
function NotificationCenter(props: {
  onUnreadCount?: (count: number) => void;
  onGotoApprovals?: () => void;
  /** 带 room_id 的通知 → 跳房间；
 * eventId 可选 → 跳房间并定位到该消息。 */
  onGotoRoom?: (roomId: string, eventId?: string) => void;
  refreshTick?: number;
  /** ：待接受邀请（sync rooms.invite 段，
 * WorkbenchPage 已随 /teams/sync 持有）——此处只做入口卡，接受/拒绝
 * UI 留在团队概览（单一事实源，Tuwunel /join 修复不重复实现）。 */
  invites?: InviteRoom[];
  /** 跳团队概览处理邀请（chat tab + 无激活房间 → 邀请区可见）。 */
  onGotoInvites?: () => void;
  // ── 待处理子页签（10/26 原顶层「待决策」tab 并入通知页；
  // P0 人工介入闭环后由 attention 单源升级为三源统一待办池）──
  /** attention 聚合 payload（全局轮询源在 WorkbenchPageData；
 * 历史区 + attention 项回查原始数据用）。 */
  attention?: AttentionPayload | null;
  /** 当前子页签是否=待处理（状态提到 WorkbenchPage：顶栏 badge 点击
   * 落点 + ui-state 持久化，刷新后保持）。 */
  attentionSubTab?: boolean;
  /** 子页签切换（通知事件流 ↔ 待处理）。 */
  onAttentionSubTabChange?: (next: boolean) => void;
  /** 面板「回答」→ 打开全局决策弹窗并定位到该条。 */
  onOpenAttentionItem?: (item: AttentionItem) => void;
  /** 面板手动刷新（绕过 30s 服务端缓存）。 */
  onRefreshAttention?: () => void;
  // ── P0 人工介入闭环：待决策 → 待处理（三源统一池）──
  /** 待处理统一口径（顶栏 banner / 通知中心角标 / 系统通知同源：
 * selectPendingTally——任务书要求三处相等，不另开口径）。 */
  tally?: PendingTally | null;
  /** pending 项「去项目」→ 工作流 tab 打开对应项目（interrupt 源）。 */
  onOpenProject?: (runId: string) => void;
}) {
  const {
    onUnreadCount,
    onGotoApprovals,
    onGotoRoom,
    refreshTick,
    invites,
    onGotoInvites,
    attention,
    attentionSubTab,
    onAttentionSubTabChange,
    onOpenAttentionItem,
    onRefreshAttention,
    tally,
    onOpenProject,
  } = props;
  const t = useThemeColors();
  const tr = useT();
  // 房间通知（团队房间 @提到我，Matrix 侧——宿主 inbox 事件
  // 无 room_id 是「点击不跳转」的根因；真·团队通知在这里）。
  const [mentions, setMentions] = React.useState<RoomMention[]>([]);
  const [mentionsLoading, setMentionsLoading] = React.useState(true);
  const [mentionsError, setMentionsError] = React.useState("");
  const [events, setEvents] = React.useState<InboxEvent[]>([]);
  const [unread, setUnread] = React.useState(0);
  const [total, setTotal] = React.useState(0);
  const [loading, setLoading] = React.useState(true);
  const [error, setError] = React.useState("");
  const [unreadOnly, setUnreadOnly] = React.useState(false);
  const [expandedId, setExpandedId] = React.useState<string | null>(null);
  const [marking, setMarking] = React.useState(false);
  // 房间级 Worker Tool Guard 审批请求——
  // 与上面「宿主待审批」（本机 QwenPaw 原生队列）不同源：Worker 的受控
  // 工具调用在 Matrix 房间发「🛡️ Approval Required」，不带 @人类，
 // 旧逻辑零提示（「只能在聊天群看见，并 @相关 worker」）。
  const [approvals, setApprovals] = React.useState<RoomApproval[]>([]);
  const [approvalsError, setApprovalsError] = React.useState("");
  const [approvalActing, setApprovalActing] = React.useState<string | null>(null);

  // force=true 绕过 15s 读缓存直回源——审批动作后的「立即+3s」双拉必须
  // 都打后端（后端审批缓冲经 sync watcher 异步 resolve，≈1-2s；若 3s 那次
  // 命中缓存，未 resolve 项会被缓存值顶回=卡片复活）。
  const loadApprovals = React.useCallback(async (force = false) => {
    try {
      const list = await fetchRoomApprovals(30, force);
      setApprovals(list);
      setApprovalsError("");
    } catch (e) {
      setApprovalsError(e instanceof Error ? e.message : String(e));
    }
  }, []);

  /** 一键批准/拒绝：向房间发带 @Worker 的审批命令（RoomChat 审批卡同款
 * 语义）。此前裸发命令（无 @）——群房间
 * _require_mention=True 时 Worker 不消费；sender 缺失（异常数据）时
 * 降级为无 @ 命令（比不发强，DM 房间本就不需要 mention）。 */
  const doApproval = React.useCallback(
    async (a: RoomApproval, action: "approve" | "deny") => {
      const key = a.event_id || a.room_id;
      setApprovalActing(key);
      try {
        const cmd = action === "approve" ? a.approve_cmd : a.deny_cmd;
        const replyTo = a.event_id
          ? { event_id: a.event_id, sender: a.sender, body: a.body }
          : undefined;
        if (!a.sender) throw new Error(tr("审批消息缺少发送者，无法定向 @，请去房间手动处理"));
        await sendApprovalCommand(a.room_id, a.sender, cmd, replyTo);
        antd.message.success(
          action === "approve" ? tr("已发送批准命令（Worker 继续执行）") : tr("已发送拒绝命令"),
        );
        setApprovals((prev) => prev.filter((x) => (x.event_id || x.room_id) !== key));
        // 审批命令发出后后端缓冲经 sync watcher 异步 resolve（≈1-2s）——
        // 乐观删除后若轮询在 resolve 窗口前拉取，未清项被拉回=卡片复活。
        // 故发送成功后立即重拉 + 3s 再拉，两次都 force 直回源。
        void loadApprovals(true);
        window.setTimeout(() => void loadApprovals(true), 3000);
      } catch (e) {
        antd.message.error(e instanceof Error ? e.message : tr("发送失败"));
      } finally {
        setApprovalActing(null);
      }
    },
    [tr],
  );

  const loadMentions = React.useCallback(async (silent = false) => {
    if (!silent) setMentionsLoading(true);
    try {
      const list = await fetchRoomMentions(30);
      setMentions(list);
      setMentionsError("");
    } catch (e) {
      setMentionsError(e instanceof Error ? e.message : String(e));
    } finally {
      setMentionsLoading(false);
    }
  }, []);

  const load = React.useCallback(async () => {
    try {
      const page = await fetchInboxEvents({
        limit: 50,
        unread_only: unreadOnly,
      });
      setEvents(page.events || []);
      setUnread(page.unread_count ?? 0);
      setTotal(page.total ?? (page.events || []).length);
      setError("");
      onUnreadCount?.(page.unread_count ?? 0);
    } catch (e) {
      setError(e instanceof Error ? e.message : String(e));
    } finally {
      setLoading(false);
    }
    void loadMentions(true);
    void loadApprovals();
  }, [unreadOnly, onUnreadCount, loadMentions, loadApprovals]);

  // 手动刷新必穿透 30s inbox 缓存（["inbox"]）——统一走 useForceReload
  //（loading 状态仅初始 true、刷新从不置位，本 hook 的 loading 接管按钮）。
  const { reload, loading: reloadLoading } = useForceReload(load, ["inbox"]);

  // 30s 轮询（含未读计数 → tab badge）。
  // 旧定时器 → usePoller（30s）。任务书条件写作
  // `open && !document.hidden`，但本组件 props 无 open（实况核对）——本组件
  // 即 inbox tab 内容，useTabActive("inbox") 为等价门控（rc-tabs 保活：
  // 切走组件不卸载）。
  // 布尔快照——非 inbox tab 互切不再重渲。
  const inboxActive = useTabActive("inbox") && !document.hidden;
  // 挂载首拉（load 身份变化——如 unreadOnly 翻转——同样重拉，原码同款）。
  React.useEffect(() => {
    void load();
  }, [load]);
  usePoller({ fn: load, intervalMs: 30000, active: inboxActive });

  // SSE 事件触发（IM 式）：refreshTick 变化 → 刷新（不等轮询）。
  // 加 500ms 合并窗 + 可见性门——此前 5 类 SSE
  // 事件（mention/task_status/invite/approval_*）每帧无条件三连 GET
  // （inbox tab 隐藏/后台 tab 也跑，忙集群 ≈12 次无缓冲宿主拨号/min）。
  // 合并窗内多事件=一次 load；tab 激活+可见时补刷 pending（不丢刷新，
  // 只削突发；与 30s poller 的门控语义对齐）。
  const tickRef = React.useRef(refreshTick);
  const loadRef2 = React.useRef(load);
  loadRef2.current = load;
  const activeRef = React.useRef(inboxActive);
  activeRef.current = inboxActive;
  const pendingTick = React.useRef(false);
  const sseDebounce = React.useRef<ReturnType<typeof setTimeout> | null>(null);
  React.useEffect(() => {
    if (refreshTick === undefined || refreshTick === tickRef.current) return;
    tickRef.current = refreshTick;
    pendingTick.current = true;
    if (sseDebounce.current) return;
    sseDebounce.current = setTimeout(() => {
      sseDebounce.current = null;
      if (pendingTick.current && activeRef.current) {
        pendingTick.current = false;
        void loadRef2.current();
      }
    }, 500);
  }, [refreshTick, load]);
  // tab 激活/回前台：pending 立即补刷（不等 500ms 窗尾）。
  React.useEffect(() => {
    if (!inboxActive || !pendingTick.current) return;
    if (sseDebounce.current) {
      clearTimeout(sseDebounce.current);
      sseDebounce.current = null;
    }
    pendingTick.current = false;
    void load();
  }, [inboxActive, load]);
  // 卸载清窗。
  React.useEffect(
    () => () => {
      if (sseDebounce.current) clearTimeout(sseDebounce.current);
    },
    [],
  );

  // 待审批计数（顶部入口条，跳首页审批卡）= 房间审批源（load() 30s 轮询
  // 已含 loadApprovals）。弃用宿主 push-messages
  // 队列（远程 Worker 审批在该进程内，本机队列恒 0——首页没有）。

  // 待处理子页签计数。P0 人工介入闭环后统一走 tally（selectPendingTally——
  // 与顶栏 banner / 系统通知同一 selector，任务书要求三处相等，不另开口径）；
  // tally 未传（防御：旧调用点）回退 attention 单源过滤（旧 badge 口径）。
  const attentionPendingCount = React.useMemo(
    () =>
      (attention?.items || []).filter(
        (it) => !it.answered_locally && !it.resolved,
      ).length,
    [attention],
  );
  const pendingCount =
    tally && typeof tally.total === "number" ? tally.total : attentionPendingCount;

  const markAll = async () => {
    setMarking(true);
    try {
      await markInboxRead({ all: true });
      await load();
    } catch {
      /* 静默 */
    } finally {
      setMarking(false);
    }
  };

  const markOne = async (ev: InboxEvent) => {
    if (ev.read) return;
    try {
      await markInboxRead({ event_ids: [ev.id] });
      setEvents((prev) =>
        prev.map((e) => (e.id === ev.id ? { ...e, read: true } : e)),
      );
      setUnread((n) => Math.max(0, n - 1));
      onUnreadCount?.(Math.max(0, unread - 1));
    } catch {
      /* 静默 */
    }
  };

  const removeOne = async (ev: InboxEvent) => {
    try {
      await deleteInboxEvent(ev.id);
      setEvents((prev) => prev.filter((e) => e.id !== ev.id));
    } catch {
      /* 静默 */
    }
  };

  return (
    <div style={{ display: "grid", gap: 12 }}>
      {/* 子页签：通知（事件流）/ 待处理 N（三源统一池；10/26 原顶层 tab 并入，
 P0 人工介入闭环后由 attention 单源升级）。
 状态提到 WorkbenchPage（顶栏 badge 点击落点 + ui-state 持久化刷新后保持），
 本组件纯消费。事件流各段（审批/邀请/房间通知/宿主通知）轮询不随子页签
 停——切到待处理期间未读计数照常累计。 */}
      <antd.Tabs
        size="small"
        activeKey={attentionSubTab ? "attention" : "events"}
        onChange={(k: string) => onAttentionSubTabChange?.(k === "attention")}
        items={[
          { key: "events", label: tr("通知") },
          { key: "attention", label: `${tr("待处理")} (${pendingCount})` },
        ]}
      />
      {attentionSubTab ? (
        <PendingPanel
          attention={attention ?? null}
          onRefresh={() => onRefreshAttention?.()}
          onOpenAttentionItem={(item) => onOpenAttentionItem?.(item)}
          onOpenProject={onOpenProject}
          onGotoRoom={onGotoRoom}
        />
      ) : (
        <>
      {/* 顶部工具条 */}
      <div style={{ display: "flex", alignItems: "center", gap: 8, flexWrap: "wrap" }}>
        <antd.Typography.Title level={4} style={{ margin: 0 }}>
          <span style={{ display: "inline-flex", alignItems: "center", gap: 5 }}><BellIcon size={15} /> {tr("通知中心")}</span>
        </antd.Typography.Title>
        {unread > 0 ? (
          <antd.Badge count={unread} overflowCount={99} style={{ backgroundColor: PRIMARY }} />
        ) : null}
        <div style={{ flex: 1 }} />
        <antd.Segmented
          size="small"
          value={unreadOnly ? "unread" : "all"}
          onChange={(v: string | number) => setUnreadOnly(v === "unread")}
          options={[
            { value: "all", label: `${tr("全部")} (${total})` },
            { value: "unread", label: `${tr("未读")} (${unread})` },
          ]}
        />
        <antd.Button
          size="small"
          loading={marking}
          disabled={unread === 0}
          onClick={() => void markAll()}
        >
          <CheckIcon size={12} style={{ verticalAlign: "-1px", marginRight: 3 }} /> {tr("全部已读")}
        </antd.Button>
        <antd.Button size="small" loading={reloadLoading} onClick={() => void reload()}>
          <RefreshIcon size={12} style={{ verticalAlign: "-1px", marginRight: 3 }} /> {tr("刷新")}
        </antd.Button>
      </div>

      {/* 待审批入口（跳首页审批卡；房间审批源=Worker Tool Guard 真实队列） */}
      {approvals.length > 0 && onGotoApprovals ? (
        <div
          onClick={onGotoApprovals}
          style={{
 border: "1px solid color-mix(in srgb, var(--app-accent, #FF7F16) 40%, transparent)",
 background: "color-mix(in srgb, var(--app-accent, #FF7F16) 8%, transparent)",
            borderRadius: 10,
            padding: "10px 14px",
            cursor: "pointer",
            display: "flex",
            alignItems: "center",
            gap: 8,
          }}
        >
          <ShieldIcon size={16} />
          <span style={{ fontWeight: 600, color: PRIMARY, flex: 1 }}>
            {tr("有 {n} 条工具调用待审批", { n: approvals.length })}
          </span>
          <span style={{ color: t.textSecondary, fontSize: 12 }}>
            {tr("去首页审批")} ▸
          </span>
        </div>
      ) : null}

      {error ? (
        <div style={{ color: "#ff4d4f", fontSize: 13, display: "flex", alignItems: "center", gap: 4 }}><WarnIcon size={12} /> {error}</div>
      ) : null}

      {/* ：新邀请卡片 → 跳团队概览处理。
 OS toast/铃铛由后端 sync_watcher 写宿主收件箱（本区是面板内入口，
 防 toast 漏看——「邀请有时候收不到，要去 Element 点」）。 */}
      {invites && invites.length > 0 ? (
        <div>
          <div
            style={{
              fontSize: 13,
              fontWeight: 700,
              color: t.text,
              marginBottom: 8,
              display: "flex",
              alignItems: "center",
              gap: 6,
            }}
          >
            <span style={{ display: "inline-flex", alignItems: "center", gap: 5 }}><MailIcon size={13} /> {tr("邀请（{n}）", { n: invites.length })}</span>
            <span style={{ fontSize: 11, color: t.textSecondary, fontWeight: 400 }}>
              {tr("新房间邀请 · 点击到团队概览接受/拒绝")}
            </span>
          </div>
          <div style={{ display: "grid", gap: 6 }}>
            {invites.map((inv) => (
              <div
                key={inv.room_id}
                onClick={() => onGotoInvites?.()}
                title={tr("点击处理邀请")}
                style={{
                  border: "1px solid color-mix(in srgb, var(--app-accent, #FF7F16) 40%, transparent)",
                  borderRadius: 10,
                  padding: "8px 12px",
                  background: "color-mix(in srgb, var(--app-accent, #FF7F16) 8%, transparent)",
                  cursor: "pointer",
                }}
              >
                <div style={{ display: "flex", alignItems: "center", gap: 6, flexWrap: "wrap" }}>
                  <span style={{ fontWeight: 700, fontSize: 13, color: t.text, flex: "0 1 60%" }}>
                    {inv.name}
                  </span>
                  <span style={{ color: t.textSecondary, fontSize: 11.5 }}>
                    {tr("邀请人：")}
                    {inv.inviter ? senderShort(inv.inviter) : "—"}
                    {inv.inviter_ts ? ` · ${formatChatTime(inv.inviter_ts)}` : ""}
                  </span>
                  <span style={{ flex: 1 }} />
                  <span style={{ color: PRIMARY, fontSize: 12, fontWeight: 600 }}>
                    {tr("去处理")} ▸
                  </span>
                </div>
              </div>
            ))}
          </div>
        </div>
      ) : null}

      {/* ：房间级 Worker Tool Guard 审批请求
 ——OS toast 由 sync_watcher 推宿主收件箱，此处可一键批准/拒绝
 （向房间发 /approval 命令，RoomChat 审批卡同款语义）。 */}
      <div>
        <div
          style={{
            fontSize: 13,
            fontWeight: 700,
            color: t.text,
            marginBottom: 8,
            display: "flex",
            alignItems: "center",
            gap: 6,
          }}
        >
          <span style={{ display: "inline-flex", alignItems: "center", gap: 5 }}><ShieldIcon size={13} /> {tr("待审批请求（{n}）", { n: approvals.length })}</span>
          <span style={{ fontSize: 11, color: t.textSecondary, fontWeight: 400 }}>
            {tr("Worker 受控工具调用 · 一键批准/拒绝或去房间")}
          </span>
        </div>
        {approvalsError ? (
          <div style={{ color: t.textSecondary, fontSize: 12 }}>
            <span style={{ display: "inline-flex", alignItems: "center", gap: 4 }}><WarnIcon size={12} /> {tr("待审批请求加载失败")}：</span>{approvalsError}
          </div>
        ) : approvals.length === 0 ? (
          <div style={{ color: t.textSecondary, fontSize: 12, padding: "4px 0" }}>
            {tr("暂无待审批的工具调用")}
          </div>
        ) : (
          <div style={{ display: "grid", gap: 6 }}>
            {approvals.map((a, idx) => (
              <div
                key={a.event_id || `${a.room_id}-${idx}`}
                style={{
                  border: "1px solid rgba(245,34,45,0.35)",
                  borderRadius: 10,
                  padding: "8px 12px",
                  background: t.cardBg,
                  animation: `wbResultIn 0.25s ease-out both`,
                  animationDelay: `${Math.min(idx, 8) * 30}ms`,
                }}
              >
                <div style={{ display: "flex", alignItems: "center", gap: 6, flexWrap: "wrap" }}>
                  <span
                    style={{
                      color: PRIMARY,
                      fontWeight: 600,
                      fontSize: 12.5,
                      maxWidth: "50%",
                      overflow: "hidden",
                      textOverflow: "ellipsis",
                      whiteSpace: "nowrap",
                    }}
                  >
                    {a.room_name || a.room_id}
                  </span>
                  <span style={{ fontWeight: 600, fontSize: 12.5, color: t.text }}>
                    {senderShort(a.sender)}
                  </span>
                  <span style={{ flex: 1 }} />
                  <span style={{ color: t.textSecondary, fontSize: 11.5 }}>
                    {formatChatTime(a.ts)}
                  </span>
                </div>
                <div
                  // 15.14：clamp 走全局标准类（跨 Chromium 版本安全）。
                  className="wb-clamp-2"
                  style={{
                    fontSize: 12.5,
                    color: t.textSecondary,
                    marginTop: 2,
                    whiteSpace: "pre-wrap",
                  }}
                >
                  {a.body}
                </div>
                <div style={{ display: "flex", gap: 6, marginTop: 6, alignItems: "center" }}>
                  <antd.Button
                    size="small"
                    type="primary"
                    loading={approvalActing === (a.event_id || a.room_id)}
                    onClick={() => void doApproval(a, "approve")}
                  >
                    <CheckIcon size={12} style={{ verticalAlign: "-1px", marginRight: 3 }} /> {tr("批准")}
                  </antd.Button>
                  <antd.Button
                    size="small"
                    danger
                    disabled={approvalActing === (a.event_id || a.room_id)}
                    onClick={() => void doApproval(a, "deny")}
                  >
                    <CloseIcon size={12} style={{ verticalAlign: "-1px", marginRight: 3 }} /> {tr("拒绝")}
                  </antd.Button>
                  <antd.Button
                    size="small"
                    type="text"
                    style={{ fontSize: 11.5 }}
                    onClick={() => onGotoRoom?.(a.room_id, a.event_id || undefined)}
                  >
                    <MessageIcon size={12} style={{ verticalAlign: "-1px", marginRight: 3 }} /> {tr("去房间")}
                  </antd.Button>
                </div>
              </div>
            ))}
          </div>
        )}
      </div>

      {/* 房间通知（团队房间 @提到我 → 点击跳房间+定位消息） */}
      <div>
        <div
          style={{
            fontSize: 13,
            fontWeight: 700,
            color: t.text,
            marginBottom: 8,
            display: "flex",
            alignItems: "center",
            gap: 6,
          }}
        >
          <span style={{ display: "inline-flex", alignItems: "center", gap: 5 }}><MessageIcon size={13} /> {tr("房间通知")}</span>
          <span style={{ fontSize: 11, color: t.textSecondary, fontWeight: 400 }}>
            {tr("团队房间 @提到你 · 点击跳转对应消息")}
          </span>
        </div>
        {mentionsLoading ? (
          <antd.Skeleton active paragraph={{ rows: 2 }} />
        ) : mentionsError ? (
          <div style={{ color: t.textSecondary, fontSize: 12 }}>
            <span style={{ display: "inline-flex", alignItems: "center", gap: 4 }}><WarnIcon size={12} /> {tr("房间通知加载失败")}：</span>{mentionsError}
          </div>
        ) : mentions.length === 0 ? (
          <div style={{ color: t.textSecondary, fontSize: 12, padding: "4px 0" }}>
            {tr("暂无 @你 的房间消息")}
          </div>
        ) : (
          <div style={{ display: "grid", gap: 6 }}>
            {mentions.map((m, idx) => (
              <div
                key={m.event_id || `${m.room_id}-${idx}`}
                onClick={() => onGotoRoom?.(m.room_id, m.event_id)}
                title={tr("点击跳转对应消息")}
                style={{
                  border: `1px solid ${t.border}`,
                  borderRadius: 10,
                  padding: "8px 12px",
                  background: t.cardBg,
                  cursor: "pointer",
                  animation: `wbResultIn 0.25s ease-out both`,
                  animationDelay: `${Math.min(idx, 8) * 30}ms`,
                }}
              >
                <div
                  style={{
                    display: "flex",
                    alignItems: "center",
                    gap: 6,
                    flexWrap: "wrap",
                  }}
                >
                  <span
                    style={{
                      color: PRIMARY,
                      fontWeight: 600,
                      fontSize: 12.5,
                      maxWidth: "55%",
                      overflow: "hidden",
                      textOverflow: "ellipsis",
                      whiteSpace: "nowrap",
                    }}
                  >
                    {m.room_name || m.room_id}
                  </span>
                  <span style={{ fontWeight: 600, fontSize: 12.5, color: t.text }}>
                    {senderShort(m.sender)}
                  </span>
                  <span style={{ flex: 1 }} />
                  <span style={{ color: t.textSecondary, fontSize: 11.5 }}>
                    {formatChatTime(m.ts)}
                  </span>
                </div>
                <div
                  className="wb-clamp-2"
                  style={{
                    fontSize: 12.5,
                    color: t.textSecondary,
                    marginTop: 2,
                    whiteSpace: "pre-wrap",
                  }}
                >
                  {m.body}
                </div>
              </div>
            ))}
          </div>
        )}
      </div>

      {/* 宿主通知（本机 QwenPaw Agent 事件：审批/cron/邮件等） */}
      <div>
        <div
          style={{
            fontSize: 13,
            fontWeight: 700,
            color: t.text,
            marginBottom: 8,
            display: "flex",
            alignItems: "center",
            gap: 6,
          }}
        >
          <span style={{ display: "inline-flex", alignItems: "center", gap: 5 }}><MonitorIcon size={13} /> {tr("宿主通知")}</span>
          <span style={{ fontSize: 11, color: t.textSecondary, fontWeight: 400 }}>
            {tr("本机 QwenPaw 事件 · 与团队房间通知不同源，多数无房间可跳")}
          </span>
        </div>

      {/* 事件列表 */}
      {loading ? (
        <antd.Skeleton active paragraph={{ rows: 4 }} />
      ) : events.length === 0 ? (
        <antd.Empty
          description={
            unreadOnly ? tr("没有未读通知") : tr("暂无通知")
          }
        />
      ) : (
        <div style={{ display: "grid", gap: 8 }}>
          {events.map((ev, idx) => {
            const sev = sevColor(ev.severity, "#888");
            const isExpanded = expandedId === ev.id;
            // 房间跳转能力区分——宿主事件多数无 room_id（审批/cron/
            // 记忆等本机事件），带 room_id 的点击即跳（行为保留）。
            const evRoomId =
              typeof ev.payload?.room_id === "string"
                ? (ev.payload.room_id as string)
                : "";
            return (
              <div
                key={ev.id}
                title={
                  evRoomId
                    ? tr("点击跳转对应房间")
                    : tr("本机事件 · 无可跳转房间（点击展开/标记已读）")
                }
                style={{
                  border: `1px solid ${ev.read ? t.border : sev}`,
                  borderRadius: 10,
                  padding: "10px 12px",
                  background: ev.read ? t.cardBg : `${sev}0f`,
                  cursor: "pointer",
                  animation: `wbResultIn 0.25s ease-out both`,
                  animationDelay: `${Math.min(idx, 10) * 30}ms`,
                }}
                onClick={() => {
                  if (!ev.read) void markOne(ev);
                  // 卡片点击即跳转——带 room_id 的通知直接跳对应房间
                  //（此前只有右下角「去房间」小按钮能跳，卡片点击仅展开+已读，
                  // 用户真机反馈「通知点击要能跳转」）。无 room_id 保持展开切换。
                  if (evRoomId) {
                    onGotoRoom?.(evRoomId);
                    return;
                  }
                  setExpandedId(isExpanded ? null : ev.id);
                }}
              >
                <div style={{ display: "flex", alignItems: "flex-start", gap: 8 }}>
                  <span
                    style={{
                      width: 8,
                      height: 8,
                      borderRadius: "50%",
                      background: ev.read ? "#ccc" : sev,
                      flexShrink: 0,
                      marginTop: 5,
                    }}
                  />
                  <div style={{ flex: 1, minWidth: 0 }}>
                    <div
                      style={{
                        display: "flex",
                        alignItems: "center",
                        gap: 6,
                        flexWrap: "wrap",
                      }}
                    >
                      <span
                        style={{
                          fontWeight: ev.read ? 500 : 700,
                          fontSize: 13.5,
                          color: t.text,
                        }}
                      >
                        {ev.title}
                      </span>
                      {ev.severity ? (
                        <antd.Tag color={sev} style={{ margin: 0, fontSize: 11 }}>
                          {ev.severity}
                        </antd.Tag>
                      ) : null}
                      {!ev.read ? (
                        <span style={{ color: sev, fontSize: 11, fontWeight: 700 }}>
                          {tr("未读")}
                        </span>
                      ) : null}
                      <span style={{ flex: 1 }} />
                      <span style={{ color: t.textSecondary, fontSize: 11.5 }}>
                        {formatChatTime(ev.created_at)}
                      </span>
                    </div>
                    {/* 15.14：展开=全文（无 clamp 类），收起=wb-clamp-2。 */}
                    <div
                      className={isExpanded ? undefined : "wb-clamp-2"}
                      style={{
                        fontSize: 12.5,
                        color: t.textSecondary,
                        marginTop: 2,
                        whiteSpace: "pre-wrap",
                      }}
                    >
                      {ev.body}
                    </div>
                    <div
                      style={{
                        display: "flex",
                        alignItems: "center",
                        gap: 8,
                        marginTop: 4,
                      }}
                    >
                      {ev.agent_id ? (
                        <span style={{ color: t.textSecondary, fontSize: 11 }}>
                          {String(ev.agent_id).split(":")[0].replace(/^@/, "")}
                        </span>
                      ) : null}
                      {ev.source_type ? (
                        <span style={{ color: t.textSecondary, fontSize: 11 }}>
                          {ev.source_type}
                        </span>
                      ) : null}
                      <span style={{ flex: 1 }} />
                      {typeof ev.payload?.room_id === "string" && ev.payload.room_id ? (
                        <antd.Button
                          type="text"
                          size="small"
                          style={{ fontSize: 11, padding: "0 4px" }}
                          onClick={(e: ReactNS.MouseEvent) => {
                            e.stopPropagation();
                            onGotoRoom?.(String(ev.payload?.room_id));
                          }}
                          title={tr("去房间")}
                        >
                          <MessageIcon size={12} style={{ verticalAlign: "-1px", marginRight: 3 }} /> {tr("去房间")}
                        </antd.Button>
                      ) : null}
                      <antd.Button
                        type="text"
                        size="small"
                        style={{ fontSize: 11, padding: "0 4px" }}
                        onClick={(e: ReactNS.MouseEvent) => {
                          e.stopPropagation();
                          void removeOne(ev);
                        }}
                        title={tr("删除")}
                      >
                        <TrashIcon size={12} />
                      </antd.Button>
                    </div>
                  </div>
                </div>
              </div>
            );
          })}
        </div>
      )}
      </div>
        </>
      )}
    </div>
  );
}

// ── 团队视角（#1503）辅助 ─────────────────────────────────────────────
/** 团队视角状态筛选（#1503 契约 status 参数逐字）。 */
type TeamStatus = "open" | "overdue" | "resolved" | "all";

/** 团队名列表（复用既有 teams 域 fetchTeamsStructure——自身 15s 缓存 +
 * SWR；WorkbenchPageData 定期轮询，此处正常命中缓存、不发新请求）。
 * 模块级缓存：每次页面生命周期只拉一次（失败置空列表，下次再试）。 */
let teamNamesCache: string[] | null = null;
async function listTeamNames(): Promise<string[]> {
  if (teamNamesCache) return teamNamesCache;
  try {
    const { tree } = await fetchTeamsStructure();
    const names: string[] = [];
    for (const tm of tree || []) {
      const name = (tm.team_name || "").trim();
      if (name && !names.includes(name)) names.push(name);
    }
    teamNamesCache = names;
    return names;
  } catch {
    return [];
  }
}

/** ISO 时刻（团队视角行 requestedAt）→「YYYY-MM-DD HH:mm」；解析失败原样。 */
function fmtIso(iso?: string): string {
  if (!iso) return "";
  const d = new Date(iso);
  if (isNaN(d.getTime())) return iso;
  const p = (x: number) => String(x).padStart(2, "0");
  return `${d.getFullYear()}-${p(d.getMonth() + 1)}-${p(d.getDate())} ${p(
    d.getHours(),
  )}:${p(d.getMinutes())}`;
}

/** 待处理子页签内容（P0 人工介入闭环）：pending store 三源统一池
 * （attention 决策 / interrupt 中断 / room_message @我）+ 已回答历史。
 * 与顶栏 banner / 系统通知同正源（selectPendingTally 口径），此处只负责
 * 逐条给「去哪处理」的落点——不重开炉灶另算计数。
 * 团队视角（#1503）：顶部范围选择=全部（聚合，现状行为）或单团队；
 * 选团队后按 status 拉团队级列表（404 未部署 → 黄条降级回聚合视图）。 */
function PendingPanel({
  attention,
  onRefresh,
  onOpenAttentionItem,
  onOpenProject,
  onGotoRoom,
}: {
  attention: AttentionPayload | null;
  onRefresh: () => void;
  onOpenAttentionItem?: (item: AttentionItem) => void;
  onOpenProject?: (runId: string) => void;
  onGotoRoom?: (roomId: string, eventId?: string) => void;
}) {
  const t = useThemeColors();
  const tr = useT();
  const store = usePendingStore();

  // 未裁决项（resolvedIds 是去重集——答过/过期的不再列）。
  // 最早创建在前：等得最久的先处理（待办队列语义，非通知倒序）。
  const items = React.useMemo(
    () =>
      store.items
        .filter((p) => !store.resolvedIds.has(p.id))
        .sort((a, b) => a.createdAt - b.createdAt),
    [store.items, store.resolvedIds],
  );

  // attention 源回查原始 AttentionItem（「回答」→ 全局决策弹窗定位该条）。
  // key 与 pending 项 id 同构：`${taskId}:${kind||"other"}:${attempt??1}`
  // （WorkbenchPageData.syncPendingAttention 同一去重键）。
  const attentionById = React.useMemo(() => {
    const m = new Map<string, AttentionItem>();
    for (const it of attention?.items || []) {
      m.set(`${it.task_id}:${it.kind || "other"}:${it.attempt ?? 1}`, it);
    }
    return m;
  }, [attention]);

  // ── 团队视角（#1503）：scope=""=全部（聚合，现状行为不变）；
  // 非空=团队名（团队级列表，status 筛选 open/overdue/resolved/all）。 ──
  const [scopeTeam, setScopeTeam] = React.useState("");
  const [teamStatus, setTeamStatus] = React.useState<TeamStatus>("open");
  const [teamRows, setTeamRows] = React.useState<TeamAttentionRow[] | null>(null);
  const [teamSkipped, setTeamSkipped] = React.useState(0);
  const [teamUnsupported, setTeamUnsupported] = React.useState(false);
  const [teamLoading, setTeamLoading] = React.useState(false);
  const [teamError, setTeamError] = React.useState("");
  const [teamNames, setTeamNames] = React.useState<string[] | null>(null);
  const teamSeq = React.useRef(0);

  // 团队名：面板打开拉一次并缓存（模块级；命中 teams 域既有缓存）。
  React.useEffect(() => {
    if (teamNames !== null) return;
    let alive = true;
    void listTeamNames().then((names) => {
      if (alive) setTeamNames(names);
    });
    return () => {
      alive = false;
    };
  }, [teamNames]);

  // 切团队 / 切筛选都重拉（404 → unsupported=true 不抛错，UI 降级）。
  const loadTeamAttention = React.useCallback(
    async (team: string, status: TeamStatus) => {
      const seq = ++teamSeq.current;
      setTeamLoading(true);
      setTeamError("");
      setTeamRows(null);
      setTeamSkipped(0);
      setTeamUnsupported(false);
      try {
        const res = await fetchTeamAttention(team, status);
        if (seq !== teamSeq.current) return; // 过期响应（已切走）丢弃
        setTeamRows(res.rows);
        setTeamSkipped(res.skipped);
        setTeamUnsupported(res.unsupported);
      } catch (e) {
        if (seq !== teamSeq.current) return;
        setTeamError(e instanceof Error ? e.message : String(e));
      } finally {
        if (seq === teamSeq.current) setTeamLoading(false);
      }
    },
    [],
  );

  React.useEffect(() => {
    if (!scopeTeam) return;
    void loadTeamAttention(scopeTeam, teamStatus);
  }, [scopeTeam, teamStatus, loadTeamAttention]);

  // 团队视角降级（端点 404）：保留下方聚合内容并标注「聚合视图」。
  const teamDowngraded = scopeTeam !== "" && teamUnsupported;

  return (
    <div style={{ display: "grid", gap: 12 }}>
      {/* 工具条：范围选择（全部（聚合）+ 团队下拉；选团队后追加状态
 * 筛选）+ 条数 + 手动刷新（与事件流工具条同款，口径同源）。 */}
      <div style={{ display: "flex", alignItems: "center", gap: 8, flexWrap: "wrap" }}>
        <span style={{ fontSize: 12, color: t.textSecondary }}>{tr("团队视角")}</span>
        <antd.Select
          size="small"
          style={{ minWidth: 140 }}
          value={scopeTeam}
          onChange={(v: string) => setScopeTeam(v)}
          loading={teamNames === null}
          options={[
            { value: "", label: tr("全部（聚合）") },
            ...(teamNames || []).map((n) => ({ value: n, label: n })),
          ]}
        />
        {scopeTeam ? (
          <antd.Segmented
            size="small"
            value={teamStatus}
            onChange={(v: string | number) => setTeamStatus(v as TeamStatus)}
            options={[
              { value: "open", label: tr("待处理") },
              { value: "overdue", label: tr("逾期") },
              { value: "resolved", label: tr("已解决") },
              { value: "all", label: tr("全部") },
            ]}
          />
        ) : null}
        <div style={{ flex: 1 }} />
        <span style={{ fontSize: 13, color: t.textSecondary }}>
          {items.length > 0 ? tr("共 {n} 条待处理", { n: items.length }) : tr("当前没有待处理项")}
        </span>
        <antd.Button size="small" onClick={onRefresh}>
          <RefreshIcon size={12} style={{ verticalAlign: "-1px", marginRight: 3 }} /> {tr("刷新")}
        </antd.Button>
      </div>

      {/* 团队视角（404）：controller 未部署 #1503 → 黄条 + 下方保留聚合视图。 */}
      {teamDowngraded ? (
        <antd.Alert
          type="warning"
          showIcon
          style={{ flex: "0 0 auto" }}
          message={tr("当前控制器不支持团队视角（需 #1503）")}
        />
      ) : null}
      {/* 团队视角：坏项目读取失败被跳过（响应头 X-Attention-Skipped）。 */}
      {scopeTeam !== "" && !teamUnsupported && teamSkipped > 0 ? (
        <antd.Alert
          type="info"
          showIcon
          style={{ flex: "0 0 auto" }}
          message={tr("{n} 个项目读取失败已跳过", { n: teamSkipped })}
        />
      ) : null}

      {scopeTeam !== "" && !teamUnsupported ? (
        // ── 团队视角列表（行复用现有 pending 行样式 + 团队视角补显示）──
        teamLoading || !teamRows ? (
          <div style={{ fontSize: 12, color: t.textSecondary }}>{tr("加载中…")}</div>
        ) : teamError ? (
          <div style={{ color: "#ff4d4f", fontSize: 13, display: "flex", alignItems: "center", gap: 4 }}>
            <WarnIcon size={12} /> {teamError}
          </div>
        ) : teamRows.length === 0 ? (
          <antd.Empty
            description={tr("暂无待处理")}
            image={antd.Empty.PRESENTED_IMAGE_SIMPLE}
          />
        ) : (
          <div style={{ display: "grid", gap: 6 }}>
            {teamRows.map((row) => {
              const it = teamRowToAttentionItem(row);
              const title = it.question || it.task_id;
              // notified=null → 「未发送通知」（不推断）；非 null → 三个
              // 独立验收态拼接（sent / roomAccepted / channelAccepted===true）。
              const notified = it.notified;
              const notifParts =
                notified == null
                  ? []
                  : [
                      notified.sent ? tr("已发送") : null,
                      notified.roomAccepted ? tr("房间已接受") : null,
                      notified.channelAccepted === true ? tr("通道已接受") : null,
                    ].filter((s): s is string => Boolean(s));
              const notifLabel =
                notified == null || notifParts.length === 0
                  ? tr("未发送通知")
                  : notifParts.join(" · ");
              return (
                <div
                  key={it.task_id}
                  style={{
                    border: `1px solid ${t.border}`,
                    borderRadius: 10,
                    padding: "8px 12px",
                    background: t.cardBg,
                    display: "grid",
                    gap: 6,
                  }}
                >
                  <div style={{ display: "flex", alignItems: "center", gap: 6, flexWrap: "wrap" }}>
                    <antd.Tag
                      color={it.kind === "approval" ? "blue" : "purple"}
                      style={{ marginRight: 0 }}
                    >
                      {it.kind || "other"}
                    </antd.Tag>
                    {/* 逾期标记——服务端派生值透传展示（前端不计算）。 */}
                    {it.overdue ? (
                      <antd.Tag color="red" style={{ marginRight: 0 }}>
                        {tr("逾期")}
                      </antd.Tag>
                    ) : null}
                    {it.resolved ? (
                      <antd.Tag color="green" style={{ marginRight: 0 }}>
                        {tr("已解决")}
                      </antd.Tag>
                    ) : null}
                    <span
                      style={{
                        flex: 1,
                        minWidth: 120,
                        fontSize: 13,
                        color: t.text,
                        overflow: "hidden",
                        textOverflow: "ellipsis",
                        whiteSpace: "nowrap",
                      }}
                      title={title}
                    >
                      {title}
                    </span>
                    <span style={{ fontSize: 11, color: t.textSecondary }}>
                      {fmtIso(it.requested_at)}
                    </span>
                  </div>
                  {/* 已解决：resolvedVia / resolvedBy 补显示。 */}
                  {it.resolved && (it.resolvedVia || it.resolvedBy) ? (
                    <div style={{ fontSize: 11.5, color: t.textSecondary }}>
                      {[it.resolvedVia, it.resolvedBy].filter(Boolean).join(" · ")}
                    </div>
                  ) : null}
                  {/* 选项补显示（label + description）。 */}
                  {it.options && it.options.length > 0 ? (
                    <div style={{ display: "grid", gap: 2 }}>
                      {it.options.map((o) => (
                        <div key={o.id} style={{ fontSize: 12, color: t.textSecondary }}>
                          · {o.label}
                          {o.description ? ` — ${o.description}` : ""}
                        </div>
                      ))}
                    </div>
                  ) : null}
                  <div style={{ fontSize: 11.5, color: t.textSecondary }}>{notifLabel}</div>
                  {it.room_id && onGotoRoom ? (
                    <div>
                      <antd.Button
                        size="small"
                        type="text"
                        style={{ fontSize: 11.5 }}
                        onClick={() => onGotoRoom(it.room_id!)}
                      >
                        <MessageIcon size={12} style={{ verticalAlign: "-1px", marginRight: 3 }} /> {tr("去房间")}
                      </antd.Button>
                    </div>
                  ) : null}
                </div>
              );
            })}
          </div>
        )
      ) : (
        // ── 聚合视图（现状行为；团队视角降级时保留并标注）──
        <>
          {teamDowngraded ? (
            <antd.Tag style={{ justifySelf: "start", marginRight: 0 }}>
              {tr("聚合视图")}
            </antd.Tag>
          ) : null}
          {items.length === 0 ? (
        <antd.Empty
          description={tr("暂无待处理")}
          image={antd.Empty.PRESENTED_IMAGE_SIMPLE}
        />
      ) : (
        <div style={{ display: "grid", gap: 6 }}>
          {items.map((p) => {
            const isAttention = p.source === "attention";
            const atItem = isAttention ? attentionById.get(p.id) : undefined;
            const title =
              p.question ||
              (isAttention ? p.taskId : p.projectId || p.taskId) ||
              tr("待处理项");
            return (
              <div
                key={p.id}
                style={{
                  border: `1px solid ${t.border}`,
                  borderRadius: 10,
                  padding: "8px 12px",
                  background: t.cardBg,
                  display: "grid",
                  gap: 6,
                }}
              >
                <div style={{ display: "flex", alignItems: "center", gap: 6, flexWrap: "wrap" }}>
                  <antd.Tag
                    color={
                      p.kind === "intervention"
                        ? "orange"
                        : p.kind === "approval"
                        ? "blue"
                        : p.kind === "interrupt"
                        ? "volcano"
                        : "purple"
                    }
                    style={{ marginRight: 0 }}
                  >
                    {tr(
                      p.kind === "intervention"
                        ? "人工介入"
                        : p.kind === "approval"
                        ? "审批"
                        : p.kind === "interrupt"
                        ? "工作流中断"
                        : "@你",
                    )}
                  </antd.Tag>
                  <span
                    style={{
                      flex: 1,
                      minWidth: 120,
                      fontSize: 13,
                      color: t.text,
                      overflow: "hidden",
                      textOverflow: "ellipsis",
                      whiteSpace: "nowrap",
                    }}
                    title={title}
                  >
                    {title}
                  </span>
                  <span style={{ fontSize: 11, color: t.textSecondary }}>
                    {formatChatTime(p.createdAt)}
                  </span>
                </div>
                {p.question && p.question !== title ? (
                  <div className="wb-clamp-2" style={{ fontSize: 12, color: t.textSecondary, whiteSpace: "pre-wrap" }}>
                    {p.question}
                  </div>
                ) : null}
                <div style={{ display: "flex", gap: 6, alignItems: "center", flexWrap: "wrap" }}>
                  {isAttention && atItem && onOpenAttentionItem ? (
                    <antd.Button size="small" type="primary" onClick={() => onOpenAttentionItem(atItem)}>
                      {tr("回答")}
                    </antd.Button>
                  ) : null}
                  {p.projectId && onOpenProject ? (
                    <antd.Button size="small" onClick={() => onOpenProject(p.projectId!)}>
                      {tr("去项目")}
                    </antd.Button>
                  ) : null}
                  {p.roomId && onGotoRoom ? (
                    <antd.Button
                      size="small"
                      type="text"
                      style={{ fontSize: 11.5 }}
                      onClick={() => onGotoRoom(p.roomId!, p.eventId)}
                    >
                      <MessageIcon size={12} style={{ verticalAlign: "-1px", marginRight: 3 }} /> {tr("去房间")}
                    </antd.Button>
                  ) : null}
                </div>
              </div>
            );
          })}
        </div>
      )}
        </>
      )}

      {/* 已回答历史（复用 AttentionPanel 抽出的列表，口径不重开）。 */}
      <AttentionHistoryList history={attention?.answered_history || []} />
    </div>
  );
}

// 面板级 memo——父级（WorkbenchPage）重渲染
// 且 props 无变化时跳过（修复前全仓零 memo，切 tab 帧断 183-200ms）。
export default React.memo(NotificationCenter);
